import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-branch'),GD('git-switch'),GD('git-merge'),GD('gittutorial'),GD('gitworkflows','Git – gitworkflows'),('https://www.odoo.com/documentation/20.0/administration/on_premise/source.html','Odoo 20 – Source install')])
def dia(vi):
    t=('Hai nhánh tách ra từ main rồi được merge lại' if vi else 'Two branches split from main and merged back','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g03'%('vi' if vi else 'en'))
    b=''
    main=[(50,'C1'),(130,'C2'),(300,'C3'),(450,'M')]
    b+='<path class="dg-arrow" d="M50 50 H450" /><path class="dg-arrow" d="M130 50 L210 120 H370 L450 50" />\n'
    for x,l in main: b+='<circle class="%s" cx="%d" cy="50" r="16" /><text class="dg-title" text-anchor="middle" x="%d" y="55">%s</text>\n'%('dg-accent' if l=='M' else 'dg-box',x,x,l)
    for x,l in [(210,'F1'),(290,'F2')]: b+='<circle class="dg-box" cx="%d" cy="120" r="16" /><text class="dg-title" text-anchor="middle" x="%d" y="125">%s</text>\n'%(x,x,l)
    b+='<text class="dg-title" x="490" y="55">main</text><text class="dg-text" x="490" y="73">%s</text>\n'%('HEAD đang ở đây' if vi else 'HEAD is here')
    b+='<text class="dg-title" x="400" y="125">feature/course-level</text>\n'
    b+='<text class="dg-text" x="20" y="165">%s</text>\n'%('C3 là commit mới trên main sau khi nhánh tách ra; M là merge commit có hai commit cha.' if vi else 'C3 is a new commit on main after the branch split off; M is the merge commit with two parents.')
    return fig('640 180',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a03');base(sb)
    A=sb.P('git branch','git switch -c feature/course-price','git branch',"echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm trường học phí"','git log --oneline --graph --all','git switch main','grep -c price models/course.py','git switch feature/course-price','grep -c price models/course.py')
    B=sb.P('git switch main','git merge feature/course-price','git log --oneline --graph','git branch -d feature/course-price','git branch')
    C=sb.P('git switch -c feature/course-level',"echo \"    level = fields.Selection([('basic', 'Cơ bản'), ('adv', 'Nâng cao')])\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm trường cấp độ"','git switch main','echo "# vinc_course" > README.md','git add README.md','git commit -m "[ADD] vinc_course: README"','git merge feature/course-level','git log --oneline --graph','git branch --merged','git branch -d feature/course-level')
    D=sb.P('git switch -c feature/course-code',"echo \"    code = fields.Char(string='Mã khóa')\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm mã khóa học"','git switch main','git merge --no-ff feature/course-code','git log --oneline --graph -n 4','git branch -d feature/course-code')
    F=sb.P('git switch -c experiment/video','echo "# thử video" >> README.md','git commit -am "[IMP] vinc_course: thử nhúng video"','git switch main','git branch -d experiment/video','git branch -D experiment/video')
    H=sb.P('cat .git/HEAD','git rev-parse --short main','git branch -v')
    G=sb.P('git switch -c feature/course-sync main~2','echo "ghi chú đồng bộ" > SYNC.md','git add SYNC.md','git commit -m "[ADD] vinc_course: ghi chú đồng bộ"','git merge main','git log --oneline --graph -n 1','git switch main','git branch -D feature/course-sync')
    e=SB('a03e');base(e)
    E1=e.P('git switch -c feature/x',"echo \"    x = fields.Char()\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm trường x"','git switch main',"echo \"    y = fields.Char()\" >> models/course.py",'git switch feature/x')
    E3=e.P('git switch -c "feature/course price"','git switch -c feature/course-price')
    E2=e.P('git stash -q','git checkout HEAD~1 2>&1 | head -5','git switch -')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Nhánh là một con trỏ nhẹ tới commit, nên tạo nhánh gần như tức thì và rẻ như xóa nhánh.</strong> Nhóm nào cũng quy định mỗi tính năng một nhánh, để việc dang dở của người này không làm hỏng việc của người kia. Bài này dùng <code>git switch -c</code> để tạo nhánh cho trường mới của <code>vinc_course</code>, gộp lại bằng <code>git merge</code> (fast-forward và merge commit), xóa nhánh xong việc và cách xử lý hai tình huống hay gặp: chuyển nhánh khi còn sửa dở và <em>detached HEAD</em>.','<strong>A branch is a lightweight pointer to a commit, so a new branch appears almost instantly and removing it costs just as little.</strong> Every team agrees on one branch per feature so that one person\'s unfinished work cannot break another\'s. This part uses <code>git switch -c</code> to create branches for new <code>vinc_course</code> fields, merges them back with <code>git merge</code> (fast-forward and merge commit), deletes finished branches and handles two common situations: switching with unfinished edits and <em>detached HEAD</em>.')))
    o+=h2('nhanh-la-gi',t('Nhánh là gì và vì sao mỗi việc một nhánh','What a branch is and why one branch per task'))
    o+=p(t('Hãy tưởng tượng nhóm có ba việc đang chạy: thêm trường học phí, thêm cấp độ khóa học và sửa tài liệu. Nếu cả ba cùng commit lên một đường duy nhất, một việc dang dở sẽ lẫn vào các việc khác, và bạn không thể phát hành chỉ riêng việc đã xong. Git giải bằng nhánh: mỗi việc có một đường lịch sử riêng xuất phát từ cùng một điểm, và khi xong thì gộp (<em>merge</em>) lại vào nhánh chính.','Imagine the team has three jobs running: adding a price field, adding a course level and fixing docs. If all three commit to one single line, an unfinished job leaks into the others and you cannot release only the finished one. Git answers with branches: each job gets its own line of history starting from the same point, and when it is done you <em>merge</em> it back into the main branch.'))
    o+=dia(vi)
    o+=p(t('Về kỹ thuật, nhánh chỉ là tên gắn với một commit. Khi bạn commit, tên nhánh hiện tại tự dịch chuyển sang commit mới. <code>HEAD</code> là con trỏ cho biết bạn đang đứng ở nhánh nào. Vì không có thư mục nào được sao chép, tạo nhánh mất chưa tới một giây dù repo lớn thế nào.','Technically a branch is only a name attached to a commit. When you commit, the current branch name moves to the new commit. <code>HEAD</code> is the pointer telling you which branch you are on. Because nothing is copied, creating a branch takes under a second no matter how big the repo is.'))
    o+=tbl([t('Lệnh','Command'),t('Tác dụng','What it does')],[
        ['<code>git branch</code>',t('Liệt kê nhánh cục bộ, dấu <code>*</code> là nhánh hiện tại','List local branches; the <code>*</code> marks the current one')],
        ['<code>git branch -a</code>',t('Liệt kê cả nhánh remote (bài 4)','Also list remote branches (part 4)')],
        ['<code>git switch &lt;nhánh&gt;</code>',t('Chuyển sang nhánh có sẵn','Move to an existing branch')],
        ['<code>git switch -c &lt;nhánh&gt;</code>',t('Tạo nhánh mới từ vị trí hiện tại và chuyển sang đó','Create a new branch from here and move to it')],
        ['<code>git merge &lt;nhánh&gt;</code>',t('Gộp nhánh đó vào nhánh hiện tại','Merge that branch into the current one')],
        ['<code>git branch -d &lt;nhánh&gt;</code>',t('Xóa nhánh đã merge (an toàn)','Delete a merged branch (safe)')],
        ['<code>git branch -m &lt;mới&gt;</code>',t('Đổi tên nhánh hiện tại','Rename the current branch')]])
    o+=p(t('Bạn có thể tự nhìn thấy điều đó: file <code>.git/HEAD</code> chứa tên nhánh hiện tại, và <code>git rev-parse</code> cho biết commit mà tên nhánh đang trỏ tới.','You can see this for yourself: the <code>.git/HEAD</code> file holds the current branch name, and <code>git rev-parse</code> shows the commit a branch name points to.'))
    o+=H
    o+=p(t('Từ Git 2.23 có hai lệnh <code>git switch</code> (chuyển nhánh) và <code>git restore</code> (khôi phục file) tách nhỏ vai trò của <code>git checkout</code> vốn làm quá nhiều việc. Các hướng dẫn cũ vẫn dùng <code>git checkout</code> và lệnh đó vẫn chạy, nhưng series này dùng lệnh mới vì tên gọi nói đúng việc làm.','Since Git 2.23 the commands <code>git switch</code> (change branch) and <code>git restore</code> (restore files) split up the many jobs of <code>git checkout</code>. Older guides still use <code>git checkout</code> and it still works, but this series uses the new commands because their names say what they do.'))
    o+=h2('tao-chuyen',t('Tạo nhánh và chuyển qua lại','Creating branches and moving between them'))
    o+=p(t('Quy ước chung là đặt tên nhánh theo loại việc: <code>feature/</code> cho tính năng, <code>fix/</code> cho sửa lỗi. Ta tạo nhánh cho trường học phí, commit một thay đổi, rồi chuyển về <code>main</code>. Chú ý hai lần <code>grep</code>: nội dung file thật sự đổi theo nhánh bạn đang đứng.','A common convention is to name branches by kind of work: <code>feature/</code> for features, <code>fix/</code> for bug fixes. We create a branch for the price field, commit a change, then go back to <code>main</code>. Watch the two <code>grep</code> calls: the file content really changes with the branch you stand on.'))
    o+=A
    o+=p(t('Đồ thị <code>--graph</code> cho thấy nhánh mới đi trước <code>main</code> đúng một commit. Việc cần làm tiếp là gộp nhánh vào <code>main</code>.','The <code>--graph</code> view shows the new branch one commit ahead of <code>main</code>. The next step is to merge it into <code>main</code>.'))
    o+=p(t('Hai mẹo nhỏ giúp thao tác nhanh hơn. Thứ nhất, <code>git switch -</code> quay về nhánh bạn vừa rời, tiện khi nhảy qua lại giữa hai nhánh. Thứ hai, <code>git switch -c &lt;tên&gt; &lt;điểm-bắt-đầu&gt;</code> cho phép tạo nhánh từ một commit hay nhánh khác thay vì từ vị trí hiện tại, như ví dụ <code>main~2</code> ở phần sau. Nhớ rằng nhánh luôn bắt đầu từ chỗ bạn chỉ định, nên hãy chuyển về <code>main</code> đã cập nhật trước khi tạo nhánh tính năng mới.','Two small tips speed you up. First, <code>git switch -</code> returns to the branch you just left, handy when hopping between two branches. Second, <code>git switch -c &lt;name&gt; &lt;start-point&gt;</code> creates a branch from another commit or branch instead of from where you stand, as with <code>main~2</code> later on. Remember a branch always starts where you point it, so move to an up-to-date <code>main</code> before creating a new feature branch.'))
    o+=h2('merge',t('Merge: fast-forward và merge commit','Merging: fast-forward and merge commits'))
    o+=p(t('Lệnh <code>git merge</code> luôn chạy từ nhánh <strong>nhận</strong> thay đổi: bạn đứng ở <code>main</code> rồi gọi tên nhánh cần gộp. Có hai kết quả tùy hình dạng lịch sử. Nếu <code>main</code> không có commit nào mới kể từ lúc tách nhánh, Git chỉ cần đẩy con trỏ <code>main</code> tới trước: đó là <strong>fast-forward</strong>, không sinh commit mới.','<code>git merge</code> always runs from the branch that <strong>receives</strong> the changes: you stand on <code>main</code> and name the branch to bring in. There are two outcomes depending on the shape of history. If <code>main</code> has no new commits since the branch split off, Git just slides the <code>main</code> pointer forward: a <strong>fast-forward</strong>, no new commit.'))
    o+=B
    o+=p(t('Tình huống thực tế hơn: trong lúc bạn làm nhánh cấp độ, đồng nghiệp đã commit thêm lên <code>main</code>. Hai đường lịch sử đã rẽ, nên Git tạo một <strong>merge commit</strong> có hai commit cha để nối chúng lại. Sơ đồ ở đầu bài chính là tình huống này.','A more realistic case: while you work on the level branch a colleague commits to <code>main</code>. The two histories went separate ways, so Git creates a <strong>merge commit</strong> with two parents to join them. The diagram at the top is exactly this case.'))
    o+=C
    o+=p(t('Hãy đọc đồ thị: ngôi sao thứ hai bên trái là commit README trên <code>main</code>, nhánh bên phải là commit cấp độ, và dòng trên cùng là merge commit nối cả hai. Vì hai thay đổi nằm ở file khác nhau (hoặc khác dòng), Git tự gộp được; khi chúng đụng cùng một dòng sẽ có <em>xung đột</em>, chủ đề của bài 6. <code>git branch --merged</code> liệt kê nhánh đã nằm gọn trong nhánh hiện tại, tức là an toàn để xóa.','Read the graph: the second star on the left is the README commit on <code>main</code>, the branch on the right is the level commit, and the top line is the merge commit joining both. Because the two changes touch different files (or different lines) Git can merge them by itself; when they touch the same line you get a <em>conflict</em>, the subject of part 6. <code>git branch --merged</code> lists branches already contained in the current one, meaning they are safe to delete.'))
    o+=p(t('Nhiều nhóm muốn <em>luôn</em> có merge commit để lịch sử ghi lại “tính năng này được gộp lúc nào”, kể cả khi fast-forward được. Cờ <code>--no-ff</code> làm đúng việc đó:','Many teams want a merge commit <em>every time</em> so history records “when this feature was merged”, even when a fast-forward is possible. The <code>--no-ff</code> flag does exactly that:'))
    o+=D
    o+=h2('xoa-nhanh',t('Dọn nhánh sau khi xong việc','Cleaning up after the work is done'))
    o+=p(t('Nhánh đã merge không còn giá trị, nên xóa để danh sách gọn. <code>git branch -d</code> chỉ xóa nhánh đã được merge và từ chối nếu bạn sẽ mất commit. Muốn bỏ hẳn một thử nghiệm, dùng <code>-D</code> (viết hoa) để ép xóa, nhưng hãy chắc chắn rằng bạn không cần các commit đó nữa.','A merged branch has no more value, so delete it to keep the list tidy. <code>git branch -d</code> deletes only merged branches and refuses if you would lose commits. To drop an experiment for good use <code>-D</code> (capital) to force it, but be sure you no longer need those commits.'))
    o+=F
    o+=h2('thoi-quen',t('Thói quen giữ nhánh gọn gàng','Habits that keep branches tidy'))
    o+=ul([t('<strong>Nhánh ngắn hạn.</strong> Nhánh sống càng lâu càng lệch xa <code>main</code>, nên việc merge càng đau. Chia việc để nhánh sống vài ngày, không phải vài tuần.','<strong>Short-lived branches.</strong> The longer a branch lives the further it drifts from <code>main</code>, and the more painful the merge. Slice work so branches live days, not weeks.'),t('<strong>Một nhánh một mục đích.</strong> Đừng gom “thêm trường học phí” và “sửa báo cáo” vào cùng nhánh; khi cần hoàn tác hay review sẽ khó tách.','<strong>One purpose per branch.</strong> Do not bundle “add price field” with “fix the report”; undoing or reviewing them separately becomes hard.'),t('<strong>Không commit trực tiếp lên <code>main</code>.</strong> Hầu hết nhóm bảo vệ nhánh chính và chỉ cho gộp qua merge request (bài 5).','<strong>Never commit straight to <code>main</code>.</strong> Most teams protect the main branch and allow changes only through merge requests (part 5).'),t('<strong>Cập nhật từ <code>main</code> thường xuyên.</strong> Khi <code>main</code> có thay đổi mới, kéo chúng vào nhánh của bạn để phát hiện xung đột sớm:','<strong>Catch up with <code>main</code> often.</strong> When <code>main</code> gets new changes, bring them into your branch so conflicts show up early:')])
    o+=G
    o+=p(t('Lần này <code>git merge main</code> được chạy từ nhánh tính năng, nghĩa là nhánh tính năng là bên <em>nhận</em>. Cách này không đụng gì tới <code>main</code>, nên an toàn. Bài 8 sẽ cho thấy lựa chọn khác là <code>rebase</code>.','This time <code>git merge main</code> runs from the feature branch, so the feature branch is the <em>receiving</em> side. It does not touch <code>main</code>, which makes it safe. Part 8 shows the alternative, <code>rebase</code>.'))
    o+=h2('trong-odoo',t('Nhánh trong công việc Odoo','Branches in Odoo work'))
    o+=tbl([t('Cách dùng nhánh','Branch usage'),t('Ví dụ','Example')],[
        [t('Nhánh theo phiên bản Odoo','A branch per Odoo version'),t('Tài liệu cài từ mã nguồn dùng <code>git clone --branch 20.0 --single-branch ...</code>: nhánh <code>20.0</code> của Odoo là bản 20','The source-install documentation uses <code>git clone --branch 20.0 --single-branch ...</code>: Odoo\'s <code>20.0</code> branch is version 20')],
        [t('Nhánh theo tính năng','A branch per feature'),'<code>feature/course-price</code>, <code>feature/course-level</code>'],
        [t('Nhánh sửa lỗi','A branch for fixes'),t('<code>fix/duplicate-course-code</code> rồi merge qua merge request (bài 5)','<code>fix/duplicate-course-code</code> then merged via merge request (part 5)')],
        [t('Nhánh thử nghiệm','An experiment branch'),t('<code>experiment/video</code>, xóa bằng <code>-D</code> nếu bỏ','<code>experiment/video</code>, deleted with <code>-D</code> if abandoned')]])
    o+=p(t('Với module tùy biến cho khách hàng, nhiều nhóm giữ một nhánh ổn định cho mỗi phiên bản Odoo mà khách đang chạy (ví dụ <code>20.0</code>) và tách nhánh tính năng từ đó. Chi tiết chiến lược nhánh nằm ở bài 10.','For custom modules built for a client, many teams keep one stable branch for each Odoo version the client runs (for example <code>20.0</code>) and branch features off it. Part 10 covers branching strategies in detail.'))
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Chuyển nhánh khi còn sửa dở.</strong> Nếu file bạn sửa khác nhau giữa hai nhánh, Git từ chối để bảo vệ công việc của bạn:','<strong>Switching branches with unfinished edits.</strong> If the file you edited differs between the two branches, Git refuses to protect your work:'),
        E1,
        t('Có ba lối thoát: commit tạm, <code>git stash</code> (bài 9), hoặc bỏ thay đổi bằng <code>git restore</code> (bài 7). Đừng ép chuyển bằng cờ <code>-f</code> khi chưa hiểu nó vứt gì.','Three ways out: commit it, <code>git stash</code> (part 9), or discard it with <code>git restore</code> (part 7). Do not force the switch with <code>-f</code> before you understand what it throws away.'),
        t('<strong>Rơi vào “detached HEAD”.</strong> Gõ <code>git checkout &lt;commit&gt;</code> hay <code>git switch --detach</code> đưa HEAD tới một commit không thuộc nhánh nào. Commit tạo ra lúc này dễ bị “lạc”. Muốn giữ, hãy <code>git switch -c &lt;tên-nhánh&gt;</code>; muốn quay lại, <code>git switch -</code>:','<strong>Falling into “detached HEAD”.</strong> Running <code>git checkout &lt;commit&gt;</code> or <code>git switch --detach</code> puts HEAD on a commit that is on no branch. Commits made now are easy to lose. To keep them run <code>git switch -c &lt;branch-name&gt;</code>; to go back run <code>git switch -</code>:'),
        E2,
        t('<strong>Tên nhánh có dấu cách.</strong> Tên nhánh không được chứa khoảng trắng; hãy nối bằng dấu gạch ngang (và dùng chữ thường không dấu để dễ gõ trong terminal):','<strong>Spaces in a branch name.</strong> Branch names cannot contain spaces; join words with hyphens (and prefer lowercase ASCII so they are easy to type in a terminal):'),
        E3,
        t('<strong>Commit nhầm lên <code>main</code>.</strong> Quên tạo nhánh rồi commit thẳng lên <code>main</code> là lỗi phổ biến; hãy nhìn dấu <code>*</code> của <code>git branch</code> hoặc dòng đầu của <code>git status</code> trước khi commit. Cách cứu nằm ở bài 7.','<strong>Committing on <code>main</code> by mistake.</strong> Forgetting to create a branch and committing straight to <code>main</code> is common; look at the <code>*</code> in <code>git branch</code> or the first line of <code>git status</code> before committing. Part 7 shows the rescue.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Nhánh là con trỏ nhẹ; mỗi việc một nhánh, đặt tên <code>feature/...</code>, <code>fix/...</code>.','A branch is a light pointer; one branch per task, named <code>feature/...</code>, <code>fix/...</code>.'),t('<code>git switch -c</code> tạo và chuyển nhánh; nội dung file đổi theo nhánh.','<code>git switch -c</code> creates and moves; file content follows the branch.'),t('<code>git merge</code> chạy từ nhánh nhận: fast-forward khi lịch sử thẳng, merge commit khi đã rẽ; <code>--no-ff</code> ép luôn có merge commit.','<code>git merge</code> runs from the receiving branch: fast-forward for straight history, merge commit when diverged; <code>--no-ff</code> always forces a merge commit.'),t('<code>-d</code> xóa nhánh đã merge, <code>-D</code> ép xóa.','<code>-d</code> deletes merged branches, <code>-D</code> forces it.'),t('Còn sửa dở thì commit hoặc stash trước khi đổi nhánh.','With unfinished edits, commit or stash before changing branch.')])
    o+=p(t('Tất cả mới diễn ra trên máy bạn. Bài tiếp theo nối repo với <strong>GitLab</strong>: <code>clone</code>, <code>fetch</code>, <code>pull</code>, <code>push</code>, và tạo SSH key để không phải gõ mật khẩu mỗi lần.','So far everything happened on your machine. The next part connects the repo to <strong>GitLab</strong>: <code>clone</code>, <code>fetch</code>, <code>pull</code>, <code>push</code>, and creating an SSH key so you do not type a password every time.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
